button {
  font-family: var(--font-ui);
  font-weight: var(--weight-semibold);
  color: inherit;
  background: transparent;
  border: 0;
  border-radius: var(--radius-sm);
  padding: 0;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
