   Token-backed, asymmetric grid, max 8px border-radius, left-anchored layout.
   ========================================================================== */

/* ==================== HUB ROOT ==================== */
.games-hub-new {
  min-height: 100vh;
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-sans);
  padding-bottom: var(--space-12);
}

/* ==================== HUB HEADER ==================== */
.games-header-new {
  background: var(--bg-primary);
  padding: 0 var(--space-8);
  height: 60px;
  border-bottom: 1px solid var(--border-default);
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: sticky;
  top: 0;
  z-index: var(--z-sticky);
  gap: var(--space-4);
}

.back-btn-games {
  padding: var(--space-2) var(--space-4);
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-weight: 600;
  font-size: 0.8125rem;
  transition: all var(--duration-fast) var(--ease-standard);
  white-space: nowrap;
}

.back-btn-games:hover {
  color: var(--text-primary);
  border-color: var(--border-strong);
  background: var(--bg-secondary);
}

.games-main-title {
  margin: 0;
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  flex: 1;
  text-align: left;
}

/* Flow Mode Toggle */
.flow-mode-switch {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex-shrink: 0;
}

.mode-switch-label {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  cursor: pointer;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.mode-switch-label input[type="checkbox"] {
  accent-color: var(--accent-primary);
  width: 16px;
  height: 16px;
  cursor: pointer;
}

.mode-text {
  white-space: nowrap;
}

/* ==================== HERO BANNER ==================== */
.games-hero {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-default);
  padding: var(--space-10) var(--space-8);
  margin-bottom: var(--space-10);
}

/* One line of orientation under the header instead of a marketing hero. */
.games-intro {
  max-width: 1200px;
  margin: var(--space-6) auto var(--space-2);
  padding: 0 var(--space-8);
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.55;
  max-width: min(1200px, 68ch);
}

