+    box-shadow: none !important;
+  }
+
+  /* ---- Links ----
+     A printed link that is only a word is a dead end, so the address is printed
+     after it. Only for prose links; navigation is already hidden above. */
+  .legal-section a[href^='http']::after,
+  .lesson-sources a[href^='http']::after,
+  .entry-source-row a[href^='http']::after {
+    content: ' (' attr(href) ')';
